-- ============================================================================

-- MAANTA Nairobi 3-node seed — 150 merchants + deals

--

-- Nodes: BBS Mall (60), CBD Galleria (45), Westlands Hub (45)

-- Tiers: 60 elite + 90 standard

-- Deals: 40 elite with flash+boost, 20 elite standard-only, 90 standard merchants

--

-- Generated by scripts/generate-nairobi-merchants-seed.py — do not edit by hand.

-- Re-generate: python3 scripts/generate-nairobi-merchants-seed.py

--

-- Apply: make db-seed-nairobi-150  (or psql -f this file)

-- UUID namespace: b2000000 users · c2000000 merchants · d2000000 deals

-- ============================================================================



BEGIN;



-- 1. Demo merchant users (no auth — browse-only unless linked via test accounts seed)

INSERT INTO public.users (id, auth_uid, phone, email, full_name, role)
SELECT
  ('b2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid,
  NULL,
  '+25471' || lpad((2000000 + n)::text, 7, '0'),
  'seed.nairobi' || lpad(n::text, 3, '0') || '@maanta.app',
  'Nairobi Seed ' || lpad(n::text, 3, '0'),
  'merchant_admin'
FROM generate_series(1, 150) AS n
WHERE NOT EXISTS (
  SELECT 1 FROM public.users u
  WHERE u.id = ('b2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid
);



INSERT INTO public.merchants (
  id, user_id, merchant_name, tier, status, elite_trial_active, trial_ends_at,
  node, what3words_address, mall_name, floor, unit_number, entrance_notes,
  phone, email, whatsapp, account_balance, outstanding_arrears,
  is_visible, is_shadow_banned, onboarded_at
)
SELECT
  ('c2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid,
  ('b2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid,
  name,
  CASE WHEN elite THEN 'elite' ELSE 'standard' END,
  COALESCE(status, 'active'),
  elite AND COALESCE(status, 'active') = 'active',
  CASE WHEN elite AND COALESCE(status, 'active') = 'active' THEN NOW() + INTERVAL '30 days' END,
  node_name,
  w3w,
  node_name,
  floor,
  chr(65 + ((n - 1) % 26)) || '-' || lpad(((n - 1) % 40 + 1)::text, 2, '0'),
  'Synthetic seed shop — ask for Maanta pickup',
  '+25471' || lpad((2000000 + n)::text, 7, '0'),
  'seed.nairobi' || lpad(n::text, 3, '0') || '@maanta.app',
  '+25471' || lpad((2000000 + n)::text, 7, '0'),
  CASE WHEN elite THEN 1500.00 ELSE 400.00 END,
  0,
  COALESCE(status, 'active') = 'active',
  false,
  CASE
    WHEN status = 'pending' THEN NULL
    WHEN days IS NOT NULL THEN NOW() - (days || ' days')::interval
    ELSE NOW() - INTERVAL '2 days'
  END
FROM (
  SELECT
    n,
    (ARRAY['Eastleigh Spices', 'Habibi Grill', 'Soma Books', 'Nairobi Threads', 'Baraka Electronics', 'Savanna Shoes', 'Qorax Fashion', 'Milk & Honey Café', 'Amal Perfumes', 'Juba Cuts', 'Wajir Fresh', 'Dirac House', 'Gold Line Watches', 'Coastal Snacks', 'Horizon Optics', 'Safari Prints', 'Kismayo Kitchen', 'Pearl Beauty', 'Talisman Gifts', 'City Phone Hub', 'Nomad Leather', 'Bloom Florist', 'Starlight Fabrics', 'Yasmin Sweets', 'Atlas Sports', 'Moonlight Henna', 'Riverbank Tea', 'Orchid Salon', 'Mogadishu Fashion', 'Lantern Home', 'Cedar Pharmacy', 'Summit Gadgets', 'Oasis Juice', 'Velvet Scarves', 'Palm Dates Co', 'Northgate Tailor', 'Amber Lights', 'Copper Pot', 'Silk Road Bags', 'Breeze Laundry', 'Green Plate', 'Ivory Beads', 'Compass Travel', 'Dune Desserts', 'Echo Music', 'Flame Grill', 'Garden Fresh', 'Harbor Fish', 'Ivory Dental', 'Jade Jewelry', 'Karma Yoga', 'Lotus Spa', 'Maple Bakery', 'Nest Homeware', 'Olive Oil House', 'Pepper Pot', 'Quartz Clocks', 'Rose Attar', 'Saffron Mart', 'Tulip Kids', 'Urban Brew', 'Violet Lane', 'Willow Crafts', 'Xenon Tech', 'Yellow Door', 'Zebra Prints', 'Acacia Market', 'Bamboo House', 'Coral Bay', 'Delta Shoes', 'Ember Kitchen', 'Falcon Optics', 'Granite Home', 'Harbor Spice', 'Indigo Lane', 'Juniper Spa', 'Kite Surf Co', 'Lumen Books', 'Mosaic Gifts', 'Nova Fitness', 'Opal Beauty', 'Prism Audio', 'Quill Stationery', 'Ridge Outfitters', 'Slate Café', 'Terra Plants', 'Umber Tailor', 'Vista Travel', 'Wheat & Honey', 'Xylia Jewels', 'Yonder Market', 'Zenith Phones', 'Aloe Wellness', 'Brook Bakery', 'Citrus Bar', 'Drift Denim', 'Elmwood Home', 'Fjord Fish', 'Grove Market', 'Haven Salon', 'Iris Optics', 'Jade Garden', 'Kite Kids', 'Lark Music', 'Meadow Tea', 'Nimbus Tech', 'Onyx Barbers', 'Pine Crafts', 'Quest Books', 'Ripple Juice', 'Sage Pharmacy', 'Thistle Gifts', 'Uplift Yoga', 'Vale Market', 'Wren Café', 'Yarrow Fabrics', 'Zest Kitchen', 'Apex Sports', 'Bliss Spa', 'Canyon Gear', 'Dawn Bakery', 'Echo Lane', 'Fable Books', 'Glimmer Jewels', 'Hearth Home', 'Inlet Fish', 'Juniper Lane', 'Kestrel Optics', 'Luna Beauty', 'Mirth Market', 'Nectar Bar', 'Olive Lane', 'Prairie Tea', 'Quartz Lane', 'Ridge Market', 'Summit Lane', 'Tidal Spa', 'Umber Lane', 'Vivid Tech', 'Willow Lane', 'Xenon Lane', 'Yonder Lane', 'Zephyr Lane', 'Amber Lane', 'Breeze Lane', 'Cedar Lane', 'Delta Lane', 'Ember Lane', 'Fjord Lane', 'Grove Lane'])[n] AS name,
    CASE WHEN n BETWEEN 1 AND 60 THEN n <= 30 WHEN n BETWEEN 61 AND 105 THEN n <= 75 WHEN n BETWEEN 106 AND 150 THEN n <= 120 ELSE false END AS elite,
    CASE WHEN n BETWEEN 1 AND 60 THEN 'BBS Mall' WHEN n BETWEEN 61 AND 105 THEN 'CBD Galleria' WHEN n BETWEEN 106 AND 150 THEN 'Westlands Hub' END AS node_name,
    (ARRAY['stored.riches.shine', 'lively.scent.corner', 'market.square.entry', 'bright.mango.lane', 'calm.river.gate', 'fresh.olive.path', 'golden.spice.walk', 'happy.lemon.yard', 'ivory.palm.court', 'jolly.cedar.row', 'kind.amber.hall', 'lunar.peach.bay', 'mint.coral.dock', 'noble.wheat.farm', 'open.silver.mew', 'proud.tiger.den', 'quiet.umbra.vale', 'rapid.violet.cove', 'sunny.willow.glen', 'tidal.xenon.peak'])[1 + ((n - 1) % 20)] AS w3w,
    (ARRAY['Ground Floor', '1st Floor', '2nd Floor', 'Food Court'])[1 + ((n - 1) % 4)] AS floor,
    ov.status,
    ov.days
  FROM generate_series(1, 150) AS n
  LEFT JOIN LATERAL (
    SELECT
      CASE n WHEN 58 THEN 'pending'::text WHEN 59 THEN 'active'::text WHEN 104 THEN 'pending'::text WHEN 149 THEN 'active'::text END AS status,
      CASE n WHEN 59 THEN 75 WHEN 149 THEN 80 END AS days
  ) ov ON true
) src
WHERE NOT EXISTS (
  SELECT 1 FROM public.merchants m
  WHERE m.id = ('c2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid
);



DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'merchants' AND column_name = 'lat'
  ) THEN
    UPDATE public.merchants m
    SET
      lat = CASE
        WHEN n BETWEEN 1 AND 60 THEN -1.2746 + ((n % 10) - 5) * 0.00018
        WHEN n BETWEEN 61 AND 105 THEN -1.2864 + ((n % 10) - 5) * 0.00018
        ELSE -1.2674 + ((n % 10) - 5) * 0.00018
      END,
      lng = CASE
        WHEN n BETWEEN 1 AND 60 THEN 36.8501 + ((n % 7) - 3) * 0.00022
        WHEN n BETWEEN 61 AND 105 THEN 36.8172 + ((n % 7) - 3) * 0.00022
        ELSE 36.8075 + ((n % 7) - 3) * 0.00022
      END,
      updated_at = NOW()
    FROM generate_series(1, 150) AS n
    WHERE m.id = ('c2000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid;
  END IF;
END $$;



