    (172, 134, 'Midweek bundle deal', 'standard', false, 640, 1010, 3, '334155'),
    (173, 135, 'Store favourite pick', 'standard', false, 700, 1100, 3, '334155'),
    (174, 136, 'Seasonal offer', 'standard', false, 760, 1190, 3, '334155'),
    (175, 137, 'Counter special today', 'standard', false, 820, 1280, 3, '334155'),
    (176, 138, 'Member value deal', 'standard', false, 880, 1370, 3, '334155'),
    (177, 139, 'Fresh arrival discount', 'standard', false, 940, 1460, 3, '334155'),
    (178, 140, 'Clearance corner pick', 'standard', false, 400, 650, 3, '334155'),
    (179, 141, 'Daily value meal', 'standard', false, 460, 740, 3, '334155'),
    (180, 142, 'Shopper favourite', 'standard', false, 520, 830, 3, '334155'),
    (181, 143, 'Limited window offer', 'standard', false, 580, 920, 3, '334155'),
    (182, 144, 'In-store only deal', 'standard', false, 640, 1010, 3, '334155'),
    (183, 145, 'Weekend lunch special', 'standard', false, 700, 1100, 3, '334155'),
    (184, 146, 'Midweek bundle deal', 'standard', false, 760, 1190, 3, '334155'),
