  ) AS t(deal_n, merchant_n, title, deal_type, boost, price, compare, hours_ago, color)

)

INSERT INTO public.deals (

  id, merchant_id, node, title, description, image_url,

  discount_type, discount_value, deal_type, flash_duration_hours,

  is_active, boost_active, max_claims, claims_count, starts_at,

  price_kes, compare_at_kes, charges

)

SELECT

  ('d2000000-0000-4000-a000-' || lpad(c.deal_n::text, 12, '0'))::uuid,

  ('c2000000-0000-4000-a000-' || lpad(c.merchant_n::text, 12, '0'))::uuid,

  m.node,

  c.title,

  'Synthetic Nairobi seed deal — show Maanta code at counter.',

  'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"><rect width="400" height="300" fill="%23' || c.color || '"/><text x="200" y="145" font-family="sans-serif" font-size="20" fill="white" text-anchor="middle">' || replace(left(c.title, 26), '&', '%26') || '</text></svg>',

  'fixed',

  GREATEST(c.compare - c.price, 0),

  c.deal_type,

  6,

  CASE WHEN c.merchant_n IN (59, 149) THEN false ELSE true END,

  c.boost,

  CASE WHEN c.deal_type = 'flash' THEN 12 ELSE 25 END,

  0,

  CASE

    WHEN c.merchant_n IN (59, 149) THEN NOW() - INTERVAL '69 days'

    WHEN c.deal_type = 'flash' THEN NOW() - INTERVAL '1 hour'

    ELSE NOW() - INTERVAL '3 hours'

  END,

  c.price::numeric,

  c.compare::numeric,

  '[]'::jsonb

FROM catalogue c

JOIN public.merchants m ON m.id = ('c2000000-0000-4000-a000-' || lpad(c.merchant_n::text, 12, '0'))::uuid

WHERE NOT EXISTS (

  SELECT 1 FROM public.deals d

  WHERE d.id = ('d2000000-0000-4000-a000-' || lpad(c.deal_n::text, 12, '0'))::uuid

)

ORDER BY c.merchant_n, c.deal_n;



UPDATE public.deals d
SET
  starts_at = CASE
    WHEN d.merchant_id IN (
      SELECT id FROM public.merchants WHERE id = ('c2000000-0000-4000-a000-000000000059'::uuid)
         OR id = ('c2000000-0000-4000-a000-000000000149'::uuid)
    ) THEN d.starts_at
    WHEN d.deal_type = 'flash' THEN NOW() - INTERVAL '1 hour'
    ELSE NOW() - INTERVAL '3 hours'
  END,
  expires_at = CASE
    WHEN d.merchant_id IN (
      'c2000000-0000-4000-a000-000000000059'::uuid,
      'c2000000-0000-4000-a000-000000000149'::uuid
    ) THEN d.expires_at
    WHEN d.deal_type = 'flash' THEN NOW() + INTERVAL '5 hours'
    ELSE NOW() + INTERVAL '21 hours'
  END,
  is_active = CASE
    WHEN d.merchant_id IN (
      'c2000000-0000-4000-a000-000000000059'::uuid,
      'c2000000-0000-4000-a000-000000000149'::uuid
    ) THEN false
    ELSE true
  END,
  is_paused = false,
  updated_at = NOW()
WHERE d.id >= 'd2000000-0000-4000-a000-000000000001'::uuid
  AND d.id <= 'd2000000-0000-4000-a000-000000000999'::uuid;

COMMIT;

-- Summary
SELECT node, tier, count(*) AS merchants
FROM public.merchants
WHERE id >= 'c2000000-0000-4000-a000-000000000001'::uuid
  AND id <= 'c2000000-0000-4000-a000-000000000150'::uuid
GROUP BY node, tier
ORDER BY node, tier;

SELECT
  m.node,
  count(*) FILTER (WHERE d.deal_type = 'flash' AND d.is_active AND d.expires_at > NOW()) AS flash,
  count(*) FILTER (WHERE d.boost_active AND d.deal_type = 'standard' AND d.is_active AND d.expires_at > NOW()) AS boosted,
  count(*) FILTER (WHERE NOT d.boost_active AND d.deal_type = 'standard' AND d.is_active AND d.expires_at > NOW()) AS standard,
  count(*) FILTER (WHERE d.is_active AND d.expires_at > NOW()) AS total_live
FROM public.deals d
JOIN public.merchants m ON m.id = d.merchant_id
WHERE d.id >= 'd2000000-0000-4000-a000-000000000001'::uuid
GROUP BY m.node
ORDER BY m.node;
